export function addItem(cart, product) {
  const line = cart.lines.find((l) => l.productId === product.id);
  if (line) {
    line.quantity += 1;
  } else {
    cart.lines.push({
      productId: product.id,
      name: product.name,
      price: product.price,
      quantity: 1,
    });
  }
}

const codes = new Map([["SAVE10", 0.1]]);

export function findDiscount(input) {
  const code = input.trim();
  const rate = codes.get(code);
  return rate === undefined ? null : { code, rate };
}

export function shippingFee(subtotal) {
  if (subtotal === 0) return 0;
  return subtotal > FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;
}

export function canPlaceOrder(cart, email) {
  return !isEmpty(cart) && email.trim() !== "";
}
